using System; using System.Linq; using UnityEditor; using UnityEditor.SceneManagement; using UnityEngine; using UnityEngine.SceneManagement;
public static class HookwardenInstaller
{
 [MenuItem("Tools/Before We Fight/Install Hookwardens")]
 public static void Install(){var frames=Import("Assets/Art/Imported/Enemies/hookwarden_animated.png","Hookwarden",34,32,32);var hook=Import("Assets/Art/Imported/Enemies/hookwarden_hook_vfx.png","Hook",3,16,16);var prefab=Build(frames,hook);var scene=EditorSceneManager.OpenScene("Assets/Scenes/Arena.unity",OpenSceneMode.Single);foreach(var g in scene.GetRootGameObjects().Where(x=>x.name.StartsWith("Hookwarden ")).ToArray())UnityEngine.Object.DestroyImmediate(g);Vector2[] p={new(-8,3),new(8,-3)};for(int i=0;i<p.Length;i++){var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);go.name=$"Hookwarden {i+1:00}";go.transform.position=p[i];}EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("Hookwardens installed in Arena.");}
 static Sprite[] Import(string path,string prefix,int count,int w,int h){AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var im=(TextureImporter)AssetImporter.GetAtPath(path);im.textureType=TextureImporterType.Sprite;im.spriteImportMode=SpriteImportMode.Multiple;im.spritePixelsPerUnit=32;im.filterMode=FilterMode.Point;im.textureCompression=TextureImporterCompression.Uncompressed;im.mipmapEnabled=false;var s=new SpriteMetaData[count];for(int i=0;i<count;i++)s[i]=new SpriteMetaData{name=$"{prefix}_{i:000}",rect=new Rect(i*w,0,w,h),alignment=(int)SpriteAlignment.Center,pivot=new(.5f,.5f)};
#pragma warning disable CS0618
 im.spritesheet=s;
#pragma warning restore CS0618
 im.SaveAndReimport();return AssetDatabase.LoadAllAssetsAtPath(path).OfType<Sprite>().OrderBy(x=>x.name,StringComparer.Ordinal).ToArray();}
 static GameObject Build(Sprite[] frames,Sprite[] hook){var root=new GameObject("Hookwarden",typeof(SpriteRenderer),typeof(Rigidbody2D),typeof(CircleCollider2D),typeof(HookwardenEnemy));var sr=root.GetComponent<SpriteRenderer>();sr.sprite=frames[0];sr.sortingOrder=22;var rb=root.GetComponent<Rigidbody2D>();rb.gravityScale=0;rb.linearDamping=8;rb.freezeRotation=true;var col=root.GetComponent<CircleCollider2D>();col.radius=.38f;col.isTrigger=true;var so=new SerializedObject(root.GetComponent<HookwardenEnemy>());Set(so.FindProperty("frames"),frames);Set(so.FindProperty("hookFrames"),hook);so.ApplyModifiedPropertiesWithoutUndo();var prefab=PrefabUtility.SaveAsPrefabAsset(root,"Assets/Prefabs/Hookwarden.prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;}
 static void Set(SerializedProperty p,Sprite[] values){p.arraySize=values.Length;for(int i=0;i<values.Length;i++)p.GetArrayElementAtIndex(i).objectReferenceValue=values[i];}
}
